export const nearPlaneTint = (key: number): number => {
  const d = Math.min(NEAR_PLANE_PUSH, Math.max(0.1, NEAR_PLANE_PUSH * (key / 88)));
  const v = Math.round(255 * (1 - d));
  return (v << 16) | (v << 8) | v;
};

